/* From Uiverse.io by SharpTH - Tags: checkbox, flip */
.__UIV_SCOPE__ .cbx {
  -webkit-perspective: 20;
  perspective: 20;
  position: absolute;
  top: 50%;
  left: 50%;
  margin: -12px;
  border: 2px solid #e8e8eb;
  background: #e8e8eb;
  border-radius: 4px;
  transform: translate3d(0, 0, 0);
  cursor: pointer;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .cbx:hover {
  border-color: #0b76ef;
}

.__UIV_SCOPE__ .flip {
  display: block;
  transition: all 0.4s ease;
  transform-style: preserve-3d;
  position: relative;
  width: 20px;
  height: 20px;
}

.__UIV_SCOPE__ #cbx {
  display: none;
}

.__UIV_SCOPE__ #cbx:checked + .cbx {
  border-color: #0b76ef;
}

.__UIV_SCOPE__ #cbx:checked + .flip {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .front,
.__UIV_SCOPE__ .back {
  backface-visibility: hidden;
  position: absolute;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  border-radius: 2px;
}

.__UIV_SCOPE__ .front {
  background: #fff;
  z-index: 1;
}

.__UIV_SCOPE__ .back {
  transform: rotateY(180deg);
  background: #0b76ef;
  text-align: center;
  color: #fff;
  line-height: 20px;
  box-shadow: 0 0 0 1px #0b76ef;
}

.__UIV_SCOPE__ .back svg {
  margin-top: 3px;
  fill: none;
}

.__UIV_SCOPE__ .back svg path {
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
